import React from 'react';
// Cambiamos la ruta para que busque dentro de la carpeta components
import { FormularioPreventa } from './components/FormularioPreventa'; 

function App() {
  return (
    <div style={{ backgroundColor: '#f4f4f4', minHeight: '100vh' }}>
      <header style={{ backgroundColor: '#000', color: '#fff', padding: '10px', textAlign: 'center' }}>
        <h1>MakingPIT - Preventa Offline</h1>
      </header>
      <main style={{ display: 'flex', justifyContent: 'center', marginTop: '20px' }}>
        <FormularioPreventa />
      </main>
    </div>
  );
}

export default App;
